<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import {Head,Link,router} from '@inertiajs/vue3';import {reactive} from 'vue';const props=defineProps<{users:any,filters:any}>();const form=reactive({search:props.filters.search||'',status:props.filters.status||''});const filter=()=>router.get(route('admin.users.index'),form,{preserveState:true,replace:true});</script>
<template><Head title="Admin Users"/><AdminLayout><div class="flex items-center justify-between"><h1 class="text-2xl font-bold">Users</h1><span class="text-sm text-slate-500">{{users.total}} total</span></div><form class="mt-6 flex flex-wrap gap-3" @submit.prevent="filter"><input v-model="form.search" class="rounded border px-3 py-2" placeholder="Search name, email, username"><select v-model="form.status" class="rounded border px-3 py-2"><option value="">All statuses</option><option>active</option><option>suspended</option><option>banned</option></select><button class="rounded bg-slate-900 px-4 py-2 text-white">Filter</button></form><div class="mt-5 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-slate-500"><tr><th class="p-4">User</th><th>Status</th><th>Last active</th><th>Joined</th><th>Activity</th><th></th></tr></thead><tbody><tr v-for="user in users.data" :key="user.id" class="border-t"><td class="p-4"><b>{{user.name}}</b><div class="text-slate-500">{{user.email}}</div></td><td><span class="rounded-full bg-slate-100 px-2 py-1 capitalize">{{user.status}}</span></td><td>{{user.last_seen_at ? new Date(user.last_seen_at).toLocaleString() : 'Never'}}</td><td>{{new Date(user.created_at).toLocaleDateString()}}</td><td>{{user.conversations_count}} chats · {{user.messages_count}} msgs</td><td><Link :href="route('admin.users.show',user.id)" class="font-medium text-cyan-700">View</Link></td></tr><tr v-if="!users.data.length"><td colspan="6" class="p-8 text-center text-slate-500">No users found.</td></tr></tbody></table></div><div class="mt-4 flex gap-2"><template v-for="pageLink in users.links" :key="pageLink.label"><Link v-if="pageLink.url" :href="pageLink.url" class="rounded border px-3 py-1 text-sm" v-html="pageLink.label"/></template></div></AdminLayout></template>
